def budget_state(state: StateStore, settings: CoreSettings) -> BudgetState:
    spent = state.month_spend()
    cap = settings.budget_monthly_usd
    if spent >= cap:
        tier: Tier = "stopped"
    elif spent >= cap * settings.budget_degrade_at:
        tier = "degraded"
    else:
        tier = "normal"
